import React from 'react';

export default function ProductCard({ product, onAdd }) {
  return (
    <div className="card">
      <img src={product.image} alt={product.name} />
      <h3>{product.name}</h3>
      <p>💰 ${product.price}</p>
      <button onClick={onAdd}>Add to Cart</button>
    </div>
  );
}
